<script setup lang="ts">
import {computed,onBeforeUnmount,reactive,ref,watch} from 'vue'
import {request} from '../api'
import {temperatureCapability} from '../../models/model-temperature.mjs'
import CustomSelect from './CustomSelect.vue'
import Icon from './Icon.vue'
import ToggleSwitch from './ToggleSwitch.vue'
import ModelPricingEditor from './ModelPricingEditor.vue'
import SettingsGroup from './SettingsGroup.vue'

type Model={pricing?:Record<string,any>|null;id:string;name?:string;upstreamProvider?:string;reasoningEfforts?:string[];imageInput?:boolean;workerSupported?:boolean;temperatureSupported?:boolean;compat?:Record<string,any>}
type Provider={id:string;kind:'api-key'|'openai-auth'|'dsh';name:string;api?:string;baseURL?:string;models:Model[];catalogModels?:Model[];hasApiKey?:boolean;available?:boolean}
type Selection={providerId:string;modelId:string;reasoningEffort:string;temperature?:number}
type Assignments={conversation:Selection|null;tone:Selection|null;worker:Selection|null;groupScheduler:Selection|null;workerOverrides:Record<string,Selection>}
type ModelState={capabilities?:{temperatureV1?:boolean};version:number;providers:Provider[];assignments:Assignments}
type Draft=Provider&{apiKey:string}
const props=withDefaults(defineProps<{active?:boolean;page?:'providers'|'scheduling'}>(),{active:true,page:'providers'})
const emit=defineEmits<{refresh:[];error:[unknown];notice:[string]}>()
const state=ref<ModelState>(),drafts=reactive<Record<string,Draft>>({}),selected=ref(''),busy=ref(''),deleteConfirm=ref('')
const feedback=reactive({shared:'',providers:'',scheduling:''})
const feedbackRevision={shared:0,providers:0,scheduling:0}
function setFeedback(scope:keyof typeof feedbackRevision,message:string){feedback[scope]=message;feedbackRevision[scope]++}
const error=computed(()=>feedback.shared||feedback[props.page])
const assignments=ref<Assignments>({conversation:null,tone:null,worker:null,groupScheduler:null,workerOverrides:{}}),assignmentsBaseline=ref(''),expanded=ref(false)
const temperatureInputs=reactive<Record<string,string>>({})
const auth=ref<any>(),authInput=ref('');let authTimer:ReturnType<typeof setInterval>|undefined
const clone=<T,>(value:T):T=>JSON.parse(JSON.stringify(value))
const priceValidity=reactive<Record<string,boolean>>({}),priceSelection=reactive<Record<string,number>>({})
const priceKeys=new WeakMap<Model,number>();let priceKeySequence=0
function priceKey(model:Model){let key=priceKeys.get(model);if(key===undefined){key=++priceKeySequence;priceKeys.set(model,key)}return key}
function providerPricingValid(id:string){return !(drafts[id]?.models??[]).some((_,index)=>priceValidity[id+':'+index]===false)}
function clearPriceValidity(id:string){for(const key of Object.keys(priceValidity))if(key.startsWith(id+':'))delete priceValidity[key]}
function removeModel(index:number){const draft=editor.value;if(!draft)return;draft.models.splice(index,1);for(let i=index;i<draft.models.length;i++)priceValidity[draft.id+':'+i]=priceValidity[draft.id+':'+(i+1)]??true;delete priceValidity[draft.id+':'+draft.models.length];priceSelection[draft.id]=Math.min(priceSelection[draft.id]??0,Math.max(0,draft.models.length-1))}
const editor=computed(()=>drafts[selected.value])
const editorModels=computed(()=>{const p=editor.value;return p?[...new Map([...(p.catalogModels??[]),...p.models.filter(model=>!p.catalogModels?.some(item=>item.id===model.id))].map(model=>[model.id,model])).values()]:[]})
const kinds={ 'api-key':'API Key', 'openai-auth':'OpenAI 授权', dsh:'DeepSeek Harness' }
const protocols=[{value:'openai-completions',label:'OpenAI Chat Completions',icon:'brand:openai'},{value:'openai-responses',label:'OpenAI Responses',icon:'brand:openai'},{value:'anthropic-messages',label:'Anthropic Messages',icon:'brand:anthropic'},{value:'google-generative-ai',label:'Google Generative AI',icon:'brand:google'}]
const workers=[{id:'emotion_update',label:'心境更新'},{id:'env_update',label:'环境更新'},{id:'work_memory_convolution',label:'工作记忆压缩'},{id:'memory_dream',label:'长期记忆'},{id:'persona_dream',label:'人格更新'},{id:'dream',label:'梦境'},{id:'diary',label:'日记'},{id:'speech',label:'语音文本'},{id:'associate_memory',label:'联想记忆'}]
const globalRows=[{id:'conversation',label:'对话',icon:'chat'},{id:'tone',label:'Tone',icon:'voice'},{id:'worker',label:'Worker 默认',icon:'worker'},{id:'groupScheduler',label:'群聊调度器',icon:'people'}] as const
const effortNames:Record<string,string>={'':'默认',off:'关闭',none:'关闭（旧配置）',minimal:'最低',low:'低',medium:'中',high:'高',xhigh:'很高',max:'最高',ultra:'极高'}
const declaredEfforts=['off','minimal','low','medium','high','xhigh','max']
const assignmentDirty=computed(()=>JSON.stringify(assignments.value)!==assignmentsBaseline.value||temperatureScopes().some(scope=>Boolean(temperatureIssue(scope))))
function providerDirty(id:string){const current=drafts[id];if(!current)return false;if(!providerPricingValid(id))return true;const saved=state.value?.providers.find(p=>p.id===id);const comparable=(provider:Provider)=>{const {catalogModels,hasApiKey,available,...editable}=provider;return JSON.stringify({...editable,apiKey:undefined})};return !saved||comparable(current)!==comparable(saved)||Boolean(current.apiKey)}
const editorDirty=computed(()=>providerDirty(selected.value))
const allProviders=computed(()=>[...(state.value?.providers??[]),...Object.values(drafts).filter(p=>!state.value?.providers.some(saved=>saved.id===p.id))].filter(provider=>provider.kind!=='dsh'||provider.available!==false))
const availableKinds=computed(()=>[{value:'api-key',label:kinds['api-key']},...(!allProviders.value.some(p=>p.kind==='openai-auth')?[{value:'openai-auth',label:kinds['openai-auth']}]:[])])
const newKind=ref('api-key')
function safeError(cause:unknown){let message=cause instanceof Error?cause.message:String(cause);for(const secret of [...Object.values(drafts).flatMap(draft=>[draft.apiKey,draft.apiKey.trim()]),authInput.value]){if(secret)message=message.split(secret).join('[已隐藏密钥]')}return message}
function normalizeAssignments(value:Assignments):Assignments{const normalized={...clone(value),groupScheduler:value.groupScheduler??null};for(const selection of [normalized.conversation,normalized.tone,normalized.worker,normalized.groupScheduler,...Object.values(normalized.workerOverrides)])if(selection&&(selection.temperature as unknown)===null)delete selection.temperature;return normalized}
function applyState(next:ModelState,reset=false){
  next={...next,assignments:normalizeAssignments(next.assignments)}
  const keepAssignments=Boolean(state.value)&&!reset&&assignmentDirty.value
  const dirtyIds=new Set(Object.keys(drafts).filter(providerDirty))
  state.value=next
  for(const key of Object.keys(drafts)){if(reset||(!next.providers.some(provider=>provider.id===key)&&!dirtyIds.has(key)))delete drafts[key]}
  if(!keepAssignments){assignments.value=clone(next.assignments);clearTemperatureInputs()}
  assignmentsBaseline.value=JSON.stringify(next.assignments)
  for(const provider of next.providers){if(!drafts[provider.id]||!dirtyIds.has(provider.id))drafts[provider.id]={...clone(provider),apiKey:''};else {drafts[provider.id].catalogModels=clone(provider.catalogModels??[]);drafts[provider.id].hasApiKey=provider.hasApiKey;drafts[provider.id].available=provider.available}}
  if(!allProviders.value.some(provider=>provider.id===selected.value))selected.value=allProviders.value[0]?.id??''
}
async function load(reset=false){if(busy.value)return;busy.value='load';setFeedback('shared','');try{applyState(await request<ModelState>('/model-providers'),reset);return true}catch(cause){setFeedback('shared',safeError(cause));return false}finally{busy.value=''}}
async function reload(){const scope=props.page,revision=feedbackRevision[scope];if(await load()&&feedbackRevision[scope]===revision)setFeedback(scope,'')}
function selectProvider(id:string){selected.value=id;deleteConfirm.value=''}
function providerKeydown(event:KeyboardEvent){if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key)||busy.value)return;event.preventDefault();const ids=allProviders.value.map(provider=>provider.id),current=ids.indexOf(selected.value);const index=event.key==='Home'?0:event.key==='End'?ids.length-1:(current+(event.key==='ArrowLeft'?-1:1)+ids.length)%ids.length;if(ids[index]){selectProvider(ids[index]);(event.currentTarget as HTMLElement)?.querySelectorAll<HTMLButtonElement>('button')[index]?.focus()}}
function addProvider(){if(busy.value)return;const kind=newKind.value as 'api-key'|'openai-auth',id=kind==='api-key'?`provider-${window.crypto.randomUUID()}`:kind;drafts[id]={id,kind,name:kind==='api-key'?'':kinds[kind],api:'openai-completions',baseURL:'',models:[],apiKey:''};selected.value=id;newKind.value='api-key';deleteConfirm.value=''}
function addModel(){editor.value?.models.push({id:'',name:''})}
function toggleEffort(model:Model,effort:string){if(!declaredEfforts.includes(effort))return;const values=model.reasoningEfforts??[];model.reasoningEfforts=values.includes(effort)?values.filter(value=>value!==effort):[...values,effort]}
function toggleModel(model:Model){const draft=editor.value;if(!draft)return;const index=draft.models.findIndex(m=>m.id===model.id);if(index>=0)removeModel(index);else draft.models.push(clone(model))}
function providerReferenced(id:string){return [assignments.value.conversation,assignments.value.tone,assignments.value.worker,assignments.value.groupScheduler,...Object.values(assignments.value.workerOverrides)].some(value=>value?.providerId===id)}
async function saveProvider(){
  const draft=editor.value;if(!draft||busy.value||!state.value)return false
  if(!providerPricingValid(draft.id)){setFeedback('providers','请先修正模型价格');return false}
  const payload=clone(draft);payload.models=payload.models.map(model=>{const copy={...model};if(!copy.name?.trim())delete copy.name;return copy});busy.value='provider';setFeedback('providers','')
  try{const {apiKey,catalogModels,hasApiKey,available,...provider}=payload;const next=await request<ModelState>('/model-providers/save',{...provider,...(apiKey.trim()?{apiKey:apiKey.trim()}:{}),expectedVersion:state.value.version});
    clearPriceValidity(payload.id);delete drafts[payload.id];applyState(next);emit('refresh');emit('notice','Provider 已保存');return true
  }catch(cause){setFeedback('providers',safeError(cause));return false}finally{busy.value=''}
}
async function deleteProvider(){const draft=editor.value;if(!draft||busy.value)return;if(providerReferenced(draft.id)||savedProviderReferenced(draft.id)){setFeedback('providers','此 Provider 已用于模型调度，请先更改模型调度。');return}if(!state.value?.providers.some(p=>p.id===draft.id)){delete drafts[draft.id];selected.value=state.value?.providers[0]?.id??'';return}if(deleteConfirm.value!==draft.id){deleteConfirm.value=draft.id;return}busy.value='delete';setFeedback('providers','');try{const next=await request<ModelState>('/model-providers/delete',{id:draft.id,expectedVersion:state.value.version});delete drafts[draft.id];deleteConfirm.value='';applyState(next);emit('refresh');emit('notice','Provider 已删除')}catch(cause){setFeedback('providers',safeError(cause))}finally{busy.value=''}}
function discardProvider(){clearPriceValidity(selected.value);const saved=state.value?.providers.find(p=>p.id===selected.value);if(saved)drafts[saved.id]={...clone(saved),apiKey:''};else{delete drafts[selected.value];selected.value=state.value?.providers[0]?.id??''}setFeedback('providers','')}
async function refreshCatalog(){if(!editor.value||busy.value||!state.value?.providers.some(p=>p.id===selected.value))return;busy.value='catalog';setFeedback('providers','');try{applyState(await request<ModelState>('/model-providers/catalog',{id:selected.value}));emit('refresh')}catch(cause){setFeedback('providers',safeError(cause))}finally{busy.value=''}}
function savedProviderReferenced(id:string){const saved=state.value?.assignments;return Boolean(saved&&[saved.conversation,saved.tone,saved.worker,saved.groupScheduler,...Object.values(saved.workerOverrides)].some(selection=>selection?.providerId===id))}
function supportsScope(model:Model,scope:string){return scope==='conversation'||model.workerSupported!==false}
// Identity comes from the connection, never its editable display name or compatible API protocol.
function providerIcon(provider:Pick<Provider,'kind'|'baseURL'>){
  if(provider.kind==='openai-auth')return 'brand:openai'
  if(provider.kind!=='api-key')return 'provider'
  try{const url=new URL(provider.baseURL??'');if(url.protocol==='https:')return ({'api.openai.com':'brand:openai','api.deepseek.com':'brand:deepseek','api.anthropic.com':'brand:anthropic','generativelanguage.googleapis.com':'brand:google'} as Record<string,string>)[url.hostname]??'key'}catch{}
  return 'key'
}
function modelIcon(model:Model,provider?:Provider){
  const upstream=({'deepseek-official':'brand:deepseek','deepseek-account':'brand:deepseek','openai':'brand:openai','openai-account':'brand:openai','anthropic':'brand:anthropic','google':'brand:google'} as Record<string,string>)[model.upstreamProvider??'']
  if(upstream)return upstream
  const icon=provider&&providerIcon(provider);return icon?.startsWith('brand:')?icon:'model'
}
function providerOptions(scope:string){return (state.value?.providers??[]).filter(provider=>provider.kind!=='dsh'||provider.available!==false||savedProviderReferenced(provider.id)||providerReferenced(provider.id)).map(provider=>({value:provider.id,icon:providerIcon(provider),label:provider.name+(provider.available===false?'（不可用）':''),disabled:provider.available===false||!provider.models.some(model=>supportsScope(model,scope))}))}
function getSelection(scope:string):Selection|null{return globalRows.some(row=>row.id===scope)?assignments.value[scope as 'conversation'|'tone'|'worker'|'groupScheduler']:assignments.value.workerOverrides[scope]??null}
function setSelection(scope:string,value:Selection|null,keepInput=false){if(!keepInput)delete temperatureInputs[scope];if(globalRows.some(row=>row.id===scope))assignments.value[scope as 'conversation'|'tone'|'worker'|'groupScheduler']=value;else if(value)assignments.value.workerOverrides[scope]=value;else delete assignments.value.workerOverrides[scope]}
function modelsFor(scope:string){const selection=getSelection(scope);return state.value?.providers.find(provider=>provider.id===selection?.providerId)?.models??[]}
function modelOptions(scope:string){return modelsFor(scope).map(model=>({value:model.id,icon:modelIcon(model,state.value?.providers.find(provider=>provider.id===getSelection(scope)?.providerId)),label:(model.name||model.id)+(!supportsScope(model,scope)?'（仅对话）':''),disabled:!supportsScope(model,scope)}))}
function effortOptions(scope:string){const current=getSelection(scope),model=modelsFor(scope).find(model=>model.id===current?.modelId);return [...new Set(['',...(model?.reasoningEfforts??[]).filter(effort=>declaredEfforts.includes(effort)),...(current?.reasoningEffort?[current.reasoningEffort]:[])])].map(value=>({value,label:effortNames[value]??value}))}
function changeProvider(scope:string,providerId:string){const provider=state.value?.providers.find(p=>p.id===providerId),model=provider?.models.find(model=>supportsScope(model,scope));if(!model||provider?.available===false)return;setSelection(scope,{providerId,modelId:model.id,reasoningEffort:''})}
function changeModel(scope:string,modelId:string){const selection=getSelection(scope),model=modelsFor(scope).find(model=>model.id===modelId);if(selection&&model&&supportsScope(model,scope)){const {temperature,...rest}=selection;setSelection(scope,{...rest,modelId,reasoningEffort:''})}}
function changeEffort(scope:string,reasoningEffort:string){const selection=getSelection(scope);if(selection)setSelection(scope,{...selection,reasoningEffort})}
const temperatureAvailable=computed(()=>state.value?.capabilities?.temperatureV1===true)
function temperatureScopes(){return [...globalRows.map(row=>row.id),...Object.keys(assignments.value.workerOverrides)].filter(scope=>Boolean(getSelection(scope)))}
function clearTemperatureInputs(){for(const scope of Object.keys(temperatureInputs))delete temperatureInputs[scope]}
function temperatureText(scope:string){return Object.hasOwn(temperatureInputs,scope)?temperatureInputs[scope]:getSelection(scope)?.temperature===undefined?'':String(getSelection(scope)?.temperature)}
function temperaturePolicy(scope:string):{supported:boolean;min:number;max:number;reason?:string}{const selection=getSelection(scope),provider=state.value?.providers.find(p=>p.id===selection?.providerId),model=provider?.models.find(m=>m.id===selection?.modelId);if(!selection?.modelId||!model)return {supported:false,min:0,max:2,reason:'请先选择可用模型'};return temperatureCapability(provider,model,selection)}
function temperatureIssue(scope:string){const value=temperatureText(scope).trim();if(!value)return '';const policy=temperaturePolicy(scope);if(!policy.supported)return policy.reason??'当前模型不支持自定义温度';return /^(?:\d+(?:\.\d*)?|\.\d+)$/.test(value)&&Number.isFinite(Number(value))&&Number(value)>=policy.min&&Number(value)<=policy.max?'':`请输入 ${policy.min}–${policy.max} 之间的温度，留空使用模型默认`}
function temperatureEditable(scope:string){return temperatureAvailable.value&&temperaturePolicy(scope).supported}
function temperatureUnavailable(scope:string){return !temperatureAvailable.value?'当前服务不支持温度设置':temperaturePolicy(scope).supported?'':temperaturePolicy(scope).reason??'当前模型不支持自定义温度'}
function temperatureChangesPending(){const saved=state.value?.assignments;return temperatureScopes().some(scope=>getSelection(scope)?.temperature!==(globalRows.some(row=>row.id===scope)?saved?.[scope as 'conversation'|'tone'|'worker'|'groupScheduler']?.temperature:saved?.workerOverrides[scope]?.temperature))}

const temperatureInvalid=computed(()=>temperatureScopes().some(scope=>Boolean(temperatureIssue(scope))))
function changeTemperature(scope:string,value:string){const selection=getSelection(scope);if(!selection||!temperatureEditable(scope))return;temperatureInputs[scope]=value;if(temperatureIssue(scope))return;const {temperature,...rest}=selection;setSelection(scope,value.trim()?{...rest,temperature:Number(value)}:rest,true)}
function clearTemperature(scope:string){if(!temperatureAvailable.value)return;const selection=getSelection(scope);if(selection){const {temperature,...rest}=selection;setSelection(scope,rest)}}
function enableOverride(name:string){if(assignments.value.worker)setSelection(name,clone(assignments.value.worker));else setSelection(name,{providerId:'',modelId:'',reasoningEffort:''})}
function validateTemperatureReceipt(next:ModelState,payload:Omit<Assignments,'workerOverrides'>&{workerOverrides:Record<string,Selection|null>}){
  const unknown=()=>{throw new Error('保存结果未知：服务未确认温度设置，草稿已保留，请重新读取后核对')}
  if(!next||next.capabilities?.temperatureV1!==true||!Number.isSafeInteger(next.version)||next.version<=(state.value?.version??-1)||!Array.isArray(next.providers)||next.providers.some(provider=>!provider||typeof provider!=='object'||typeof provider.id!=='string'||typeof provider.name!=='string'||!['api-key','openai-auth','dsh'].includes(provider.kind)||!Array.isArray(provider.models)||provider.models.some(model=>!model||typeof model!=='object'||typeof model.id!=='string'))||!next.assignments||typeof next.assignments!=='object'||Array.isArray(next.assignments)||!next.assignments.workerOverrides||typeof next.assignments.workerOverrides!=='object'||Array.isArray(next.assignments.workerOverrides))unknown()
  function matches(actual:Selection|null|undefined,expected:Selection|null){if(!expected)return actual===null;if(!actual||typeof actual!=='object'||Array.isArray(actual))return false;return actual.providerId===expected.providerId&&actual.modelId===expected.modelId&&actual.reasoningEffort===expected.reasoningEffort&&(actual.temperature??undefined)===(expected.temperature??undefined)}
  for(const scope of ['conversation','tone','worker','groupScheduler'] as const)if(!Object.hasOwn(next.assignments,scope)||!matches(next.assignments[scope],payload[scope]))unknown()
  for(const [name,selection] of Object.entries(payload.workerOverrides)){const actual=next.assignments.workerOverrides[name];if(selection?!matches(actual,selection):actual!==undefined)unknown()}
}
async function saveAssignments(){if(busy.value||!state.value)return false;if(temperatureInvalid.value){setFeedback('scheduling','请先修正温度');return false;}if(!temperatureAvailable.value&&temperatureChangesPending()){setFeedback('scheduling','当前服务不支持温度设置，温度修改尚未保存');return false;}busy.value='assignments';setFeedback('scheduling','');try{const payload=clone(assignments.value);if(!temperatureAvailable.value)for(const selection of [payload.conversation,payload.tone,payload.worker,payload.groupScheduler,...Object.values(payload.workerOverrides)])if(selection)delete selection.temperature;const overrides:Record<string,Selection|null>={...payload.workerOverrides};for(const name of Object.keys(state.value.assignments.workerOverrides)){if(!Object.hasOwn(overrides,name))overrides[name]=null}const submitted={...payload,workerOverrides:overrides};const next=await request<ModelState>('/model-providers/assignments',{assignments:submitted,expectedVersion:state.value.version});if(temperatureAvailable.value)validateTemperatureReceipt(next,submitted);const normalized=normalizeAssignments(next.assignments);assignments.value=normalized;clearTemperatureInputs();assignmentsBaseline.value=JSON.stringify(normalized);applyState(next);emit('refresh');emit('notice','模型调度已保存');return true}catch(cause){setFeedback('scheduling',safeError(cause));return false}finally{busy.value=''}}
function discardAssignments(){if(state.value){clearTemperatureInputs();assignments.value=clone(state.value.assignments);assignmentsBaseline.value=JSON.stringify(state.value.assignments)}}
async function pollAuth(){try{const wasPending=auth.value?.status==='pending';auth.value=await request('/model-providers/openai-auth');if(auth.value.status!=='pending'){clearInterval(authTimer);authTimer=undefined;if(wasPending&&auth.value.authorized&&editor.value?.kind==='openai-auth')await refreshCatalog()}}catch(cause){clearInterval(authTimer);authTimer=undefined;setFeedback('providers',safeError(cause))}}
async function beginAuth(){if(busy.value)return;if(editor.value&&!state.value?.providers.some(provider=>provider.id===editor.value?.id)&&!await saveProvider())return;busy.value='auth';setFeedback('providers','');try{auth.value=await request('/model-providers/openai-auth',{action:'start'});clearInterval(authTimer);authTimer=setInterval(pollAuth,1000)}catch(cause){setFeedback('providers',safeError(cause))}finally{busy.value=''}}
async function replyAuth(cancel=false){if(busy.value)return;busy.value='auth';setFeedback('providers','');try{auth.value=await request('/model-providers/openai-auth',{id:auth.value?.id,value:authInput.value,cancel});authInput.value=''}catch(cause){setFeedback('providers',safeError(cause))}finally{busy.value=''}}
async function openDsh(){try{await window.sandbook?.openRuntimeGui()}catch(cause){setFeedback('providers',safeError(cause))}}
watch(()=>[props.active,props.page,editor.value?.kind] as const,([active,page,kind])=>{if(active&&page==='providers'&&kind==='openai-auth')void pollAuth()})
watch(()=>props.active,active=>{if(active&&!state.value&&!busy.value)void load()},{immediate:true})
onBeforeUnmount(()=>clearInterval(authTimer))
</script>

<template>
  <div class="model-settings" :aria-busy="Boolean(busy)">
    <div v-if="error" class="model-feedback" role="alert"><span>{{error}}</span><button type="button" class="text-button" :disabled="Boolean(busy)" @click="reload()">重新读取，保留草稿</button></div>
    <p v-if="!state" class="model-loading" role="status">{{busy?'读取中…':'未读取模型设置'}}</p>
    <template v-else>
      <section v-show="page==='providers'" class="model-section" aria-label="Provider">
        <div class="model-section-heading"><h3>Provider</h3><div class="provider-add"><CustomSelect v-if="availableKinds.length>1" v-model="newKind" aria-label="新增 Provider 类型" :options="availableKinds" :disabled="Boolean(busy)"/><button type="button" class="button" :disabled="Boolean(busy)" @click="addProvider"><Icon name="plus" :size="16"/>添加 Provider</button></div></div>
        <div class="provider-tabs" role="tablist" aria-label="Provider 列表" @keydown="providerKeydown"><button v-for="provider in allProviders" :key="provider.id" type="button" role="tab" :aria-selected="selected===provider.id" :tabindex="selected===provider.id?0:-1" :aria-controls="'provider-editor'" :disabled="Boolean(busy)" @click="selectProvider(provider.id)"><Icon :name="providerIcon(provider)" :size="16"/>{{drafts[provider.id]?.name||'未命名 Provider'}}</button></div>
        <form v-if="editor" id="provider-editor" class="provider-editor" @submit.prevent="saveProvider">
          <SettingsGroup title="连接设置">
            <label class="settings-card-row"><span>名称</span><input v-model="editor.name" required :disabled="Boolean(busy)" maxlength="120"/></label>
            <div class="settings-card-row"><span>类型</span><span class="model-value">{{kinds[editor.kind]}}</span></div>
            <template v-if="editor.kind==='api-key'">
              <label class="settings-card-row"><span>接口协议</span><CustomSelect v-model="editor.api" aria-label="接口协议" :options="protocols" :disabled="Boolean(busy)"/></label>
              <label class="settings-card-row"><span>接口地址</span><input v-model="editor.baseURL" type="url" required placeholder="https://api.example.com/v1" :disabled="Boolean(busy)"/></label>
              <label class="settings-card-row"><span>API Key</span><input v-model="editor.apiKey" type="password" autocomplete="new-password" :placeholder="editor.hasApiKey?'留空保留原密钥':'输入 API Key'" :disabled="Boolean(busy)"/></label>
            </template>
            <div v-if="editor.kind==='openai-auth'" class="settings-card-row"><span>OpenAI 授权<span v-if="auth?.authorized"> · 已授权</span></span><div class="model-actions"><button type="button" class="button" :disabled="Boolean(busy)||auth?.status==='pending'" @click="beginAuth">{{auth?.authorized?'重新授权':'授权 OpenAI'}}</button><a v-if="auth?.url" class="button" :href="auth.url" target="_blank" rel="noopener">打开授权页面</a><span v-if="auth?.userCode">{{auth.userCode}}</span><button v-if="auth?.status==='pending'" type="button" class="button" :disabled="Boolean(busy)" @click="replyAuth(true)">取消授权</button><span v-if="auth?.error" role="alert">{{auth.error}}</span></div></div>
            <div v-if="editor.kind==='openai-auth'&&auth?.prompt" class="settings-card-row"><label class="model-field">{{auth.prompt.message}}<input v-model="authInput" :placeholder="auth.prompt.placeholder" autocomplete="off" :disabled="Boolean(busy)"/></label><button type="button" class="button" :disabled="Boolean(busy)||!authInput" @click="replyAuth()">提交</button></div>
          </SettingsGroup>
          <SettingsGroup title="可选模型">
            <template v-if="editor.kind==='api-key'">
              <template v-for="(model,index) in editor.models" :key="index">
                <label class="settings-card-row"><span>模型 ID</span><input v-model="model.id" required :disabled="Boolean(busy)"/></label>
                <label class="settings-card-row"><span>显示名称</span><input v-model="model.name" :disabled="Boolean(busy)"/></label>
                <div class="settings-card-row"><span>思考深度</span><details class="effort-editor"><summary>思考深度<Icon name="down" :size="14"/></summary><div class="effort-options"><button v-for="effort in declaredEfforts" :key="effort" type="button" role="checkbox" :aria-checked="model.reasoningEfforts?.includes(effort)??false" :disabled="Boolean(busy)" @click="toggleEffort(model,effort)"><Icon v-if="model.reasoningEfforts?.includes(effort)" name="check" :size="14"/>{{effortNames[effort]}}</button></div></details></div>
                <div class="settings-card-row"><span>图像输入</span><div class="model-actions"><ToggleSwitch :model-value="Boolean(model.imageInput)" :aria-label="`${model.name||model.id||index+1} 图像输入`" :disabled="Boolean(busy)" @update:model-value="model.imageInput=$event"/><button type="button" class="icon-button model-remove" :aria-label="`移除模型 ${model.name||model.id||index+1}`" :disabled="Boolean(busy)" @click="removeModel(index)"><Icon name="close" :size="16"/></button></div></div>
              </template>
            </template>
            <template v-else><div v-for="model in editorModels" :key="model.id" class="settings-card-row"><span class="model-identity"><Icon :name="modelIcon(model,editor)" :size="16"/>{{model.name||model.id}}</span><ToggleSwitch :model-value="editor.models.some(m=>m.id===model.id)" :aria-label="model.name||model.id" :disabled="Boolean(busy)" @update:model-value="toggleModel(model)"/></div><div v-if="!editorModels.length" class="settings-card-row model-empty">暂无可用模型</div></template>
            <template #footer><button v-if="editor.kind==='api-key'" type="button" class="text-button" :disabled="Boolean(busy)" @click="addModel"><Icon name="plus" :size="16"/>添加模型</button><template v-else><button v-if="editor.kind==='dsh'" type="button" class="button" @click="openDsh">打开 DSH</button><button type="button" class="button" :disabled="Boolean(busy)||!state.providers.some(p=>p.id===selected)" @click="refreshCatalog"><Icon name="refresh" :size="16"/>刷新目录</button></template></template>
          </SettingsGroup>
          <SettingsGroup v-for="provider in Object.values(drafts)" :key="provider.id" v-show="selected===provider.id&&provider.models.length>0" title="模型价格" class="provider-pricing" aria-label="模型价格设置">
            <label v-if="provider.models.length" class="settings-card-row"><span>模型价格</span><CustomSelect :model-value="priceSelection[provider.id]??0" @update:model-value="priceSelection[provider.id]=$event" :options="provider.models.map((model,index)=>({value:index,label:model.name||model.id||'未命名模型'}))" :disabled="Boolean(busy)" :aria-label="provider.name+' 价格模型'"/></label>
            <div v-for="(model,index) in provider.models" :key="priceKey(model)" v-show="index===(priceSelection[provider.id]??0)" class="settings-card-row pricing-editor-row"><ModelPricingEditor v-model="model.pricing" :disabled="Boolean(busy)" @validity="priceValidity[provider.id+':'+index]=$event"/></div>
          </SettingsGroup>
          <div class="model-footer"><button v-if="editor.kind==='api-key'" type="button" class="text-button" :disabled="Boolean(busy)||providerReferenced(editor.id)||savedProviderReferenced(editor.id)" @click="deleteProvider">{{deleteConfirm===editor.id?'确认删除 Provider':'删除 Provider'}}</button><button v-if="deleteConfirm===editor.id" type="button" class="text-button" @click="deleteConfirm=''">取消</button><span class="footer-spacer"/><button v-if="editorDirty" type="button" class="button" :disabled="Boolean(busy)" @click="discardProvider">放弃</button><button class="button primary" :disabled="Boolean(busy)||!editorDirty||!editor.name.trim()||!providerPricingValid(editor.id)"><Icon name="save" :size="16"/>{{busy==='provider'?'保存中…':'保存 Provider'}}</button></div>
        </form>
      </section>
      <section v-show="page==='scheduling'" class="model-section" aria-label="模型调度">
        <SettingsGroup v-for="row in globalRows" :key="row.id" :title="row.label">
          <div v-if="row.id==='groupScheduler'" class="settings-card-row"><span :class="{'inherited-label':!getSelection(row.id)}">{{getSelection(row.id)?'单独设置':'继承 Worker 默认'}}</span><button type="button" class="text-button" :disabled="Boolean(busy)" @click="getSelection(row.id)?setSelection(row.id,null):enableOverride(row.id)">{{getSelection(row.id)?'恢复继承':'单独设置'}}</button></div>
          <template v-if="row.id!=='groupScheduler'||getSelection(row.id)">
          <label class="settings-card-row"><span class="model-identity"><Icon :name="row.icon" :size="16"/>Provider</span><CustomSelect :model-value="getSelection(row.id)?.providerId??''" :aria-label="`${row.label} Provider`" :options="providerOptions(row.id)" :disabled="Boolean(busy)" @update:model-value="changeProvider(row.id,$event)"/></label>
          <label class="settings-card-row"><span>模型</span><CustomSelect :model-value="getSelection(row.id)?.modelId??''" :aria-label="`${row.label}模型`" icon="model" :options="modelOptions(row.id)" :disabled="Boolean(busy)||!getSelection(row.id)?.providerId" @update:model-value="changeModel(row.id,$event)"/></label>
          <label class="settings-card-row"><span>思考深度</span><CustomSelect :model-value="getSelection(row.id)?.reasoningEffort??''" :aria-label="`${row.label}思考深度`" icon="brain" :options="effortOptions(row.id)" :disabled="Boolean(busy)||!getSelection(row.id)?.modelId||effortOptions(row.id).length===1" @update:model-value="changeEffort(row.id,$event)"/></label>
          <div class="settings-card-row temperature-row"><label :for="`temperature-${row.id}`">温度</label><div class="temperature-field"><div class="temperature-control"><input :id="`temperature-${row.id}`" :value="temperatureText(row.id)" type="text" inputmode="decimal" autocomplete="off" placeholder="模型默认" :aria-label="`${row.label}温度`" :aria-invalid="Boolean(temperatureIssue(row.id))" :aria-describedby="temperatureIssue(row.id)||temperatureUnavailable(row.id)?`temperature-${row.id}-feedback`:undefined" :disabled="Boolean(busy)||!temperatureEditable(row.id)" @input="changeTemperature(row.id,($event.target as HTMLInputElement).value)"/><button v-if="getSelection(row.id)?.temperature!==undefined||temperatureText(row.id)" type="button" class="text-button" :aria-label="`${row.label}温度恢复模型默认`" :disabled="Boolean(busy)||!temperatureAvailable" @click="clearTemperature(row.id)">模型默认</button></div><p v-if="temperatureIssue(row.id)||temperatureUnavailable(row.id)" :id="`temperature-${row.id}-feedback`" :class="{'temperature-error':temperatureIssue(row.id)}" :role="temperatureIssue(row.id)?'alert':undefined">{{temperatureIssue(row.id)||temperatureUnavailable(row.id)}}</p></div></div>
          </template>
        </SettingsGroup>
        <button type="button" class="worker-disclosure" :aria-expanded="expanded" aria-controls="worker-model-overrides" @click="expanded=!expanded"><Icon :name="expanded?'down':'chevron'" :size="16"/>Worker 单独设置</button>
        <div v-show="expanded" id="worker-model-overrides">
          <SettingsGroup v-for="worker in workers" :key="worker.id" :title="worker.label">
            <div class="settings-card-row"><span v-if="!getSelection(worker.id)" class="inherited-label">继承 Worker 默认</span><span v-else class="model-identity"><Icon :name="`worker:${worker.id}`" :size="16"/>{{worker.label}}</span><button type="button" class="text-button" :disabled="Boolean(busy)" @click="getSelection(worker.id)?setSelection(worker.id,null):enableOverride(worker.id)">{{getSelection(worker.id)?'恢复继承':'单独设置'}}</button></div>
            <template v-if="getSelection(worker.id)">
              <label class="settings-card-row"><span>Provider</span><CustomSelect :model-value="getSelection(worker.id)?.providerId??''" :aria-label="`${worker.label} Provider`" :options="providerOptions(worker.id)" :disabled="Boolean(busy)" @update:model-value="changeProvider(worker.id,$event)"/></label>
              <label class="settings-card-row"><span>模型</span><CustomSelect :model-value="getSelection(worker.id)?.modelId??''" :aria-label="`${worker.label}模型`" icon="model" :options="modelOptions(worker.id)" :disabled="Boolean(busy)" @update:model-value="changeModel(worker.id,$event)"/></label>
              <label class="settings-card-row"><span>思考深度</span><CustomSelect :model-value="getSelection(worker.id)?.reasoningEffort??''" :aria-label="`${worker.label}思考深度`" icon="brain" :options="effortOptions(worker.id)" :disabled="Boolean(busy)||effortOptions(worker.id).length===1" @update:model-value="changeEffort(worker.id,$event)"/></label>
          <div class="settings-card-row temperature-row"><label :for="`temperature-${worker.id}`">温度</label><div class="temperature-field"><div class="temperature-control"><input :id="`temperature-${worker.id}`" :value="temperatureText(worker.id)" type="text" inputmode="decimal" autocomplete="off" placeholder="模型默认" :aria-label="`${worker.label}温度`" :aria-invalid="Boolean(temperatureIssue(worker.id))" :aria-describedby="temperatureIssue(worker.id)||temperatureUnavailable(worker.id)?`temperature-${worker.id}-feedback`:undefined" :disabled="Boolean(busy)||!temperatureEditable(worker.id)" @input="changeTemperature(worker.id,($event.target as HTMLInputElement).value)"/><button v-if="getSelection(worker.id)?.temperature!==undefined||temperatureText(worker.id)" type="button" class="text-button" :aria-label="`${worker.label}温度恢复模型默认`" :disabled="Boolean(busy)||!temperatureAvailable" @click="clearTemperature(worker.id)">模型默认</button></div><p v-if="temperatureIssue(worker.id)||temperatureUnavailable(worker.id)" :id="`temperature-${worker.id}-feedback`" :class="{'temperature-error':temperatureIssue(worker.id)}" :role="temperatureIssue(worker.id)?'alert':undefined">{{temperatureIssue(worker.id)||temperatureUnavailable(worker.id)}}</p></div></div>
            </template>
          </SettingsGroup>
        </div>
        <div class="model-footer"><span class="footer-spacer"/><button v-if="assignmentDirty" type="button" class="button" :disabled="Boolean(busy)" @click="discardAssignments">放弃</button><button type="button" class="button primary" :disabled="Boolean(busy)||!assignmentDirty||temperatureInvalid" @click="saveAssignments"><Icon name="save" :size="16"/>{{busy==='assignments'?'保存中…':'保存模型调度'}}</button></div>
      </section>
    </template>
  </div>
</template>

